[
  {
    "statement": "The creation of long flexible habitats (>50 mm) on subtidal artificial structures was found to support macroalgae, non-mobile invertebrates, and fish species that were not present on surfaces without the flexible habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats altered the composition of the non-mobile invertebrate community.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Short flexible habitats (1–50 mm) had mixed effects on the composition of both mobile and non-mobile invertebrate communities.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Short flexible habitats did not lead to an increase in the species richness of mobile or non-mobile invertebrates.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Short flexible habitats showed mixed effects on the abundance of mobile and non-mobile invertebrates.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Long flexible habitats had mixed effects on the abundance of mobile and non-mobile invertebrates.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long habitats supported a higher combined biomass of macroalgae and invertebrates, primarily mussels, compared to structure surfaces without such habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "For fish populations, long habitats had mixed effects on the abundance of fish and seahorses.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Short habitats had mixed effects on seahorse abundance.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Seahorses used the long flexible habitats created on subtidal artificial structures.",
    "citations": [
      "3451"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating large protrusions or ridges (>50 mm) on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3443",
      "3445"
    ]
  },
  {
    "statement": "There is no evidence to indicate whether creating large protrusions or ridges (>50 mm) on subtidal artificial structures has any desirable or harmful effects.",
    "citations": [
      "3443",
      "3445"
    ]
  }
]

[
  {
    "statement": "Studies in Australian estuaries have examined the effects of transplanting or seeding organisms onto intertidal artificial structures.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Transplanted oysters were found to support macroalgae, mobile and non-mobile invertebrates, and fish species that were absent on structures without oysters.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The effects of transplanting organisms on combined macroalgae and invertebrate species richness and diversity were mixed.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The mixed effects on species richness and diversity depended on the site and the physical characteristics of the structure's surface.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In one study, transplanting oysters increased mobile invertebrate species richness.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Transplanting oysters or coralline algae did not lead to an increase in fish species richness or abundance in two out of three studies.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study found no increase in the combined abundance of macroalgae and invertebrates after transplanting oysters.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The survival of invertebrates transplanted onto intertidal artificial structures varied based on the species, the site, and the presence of features like grooves and ridges on the surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study noted that transplanting oysters did not increase the time fish spent interacting with the surfaces of the artificial structures.",
    "citations": [
      "3472"
    ]
  }
]

[
  {
    "statement": "Creating hole habitats larger than 50 mm on intertidal artificial structures is the most effective method for increasing species richness and diversity.",
    "citations": []
  },
  {
    "statement": "Creating hole habitats, rock pools, or grooves on intertidal artificial structures increased the combined macroalgae and invertebrate species diversity and/or richness on structure surfaces.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats, rock pools, or grooves on intertidal artificial structures supported species that were absent from structure surfaces without these features.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Creating natural rocky reef topography on intertidal artificial structures did not increase the combined macroalgae and invertebrate species richness.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Creating short flexible habitats between 1 and 50 mm on intertidal artificial structures decreased the combined macroalgae, invertebrate, and fish species richness.",
    "citations": [
      "3459"
    ]
  }
]

[
  {
    "statement": "In European marine environments, creating textured surfaces on intertidal structures has shown varied outcomes.",
    "citations": []
  },
  {
    "statement": "In the UK, creating textured surfaces along with using environmentally-sensitive material had mixed effects on the combined macroalgae and invertebrate species richness, depending on the texture and site.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "In the Netherlands, textured surfaces did not increase macroalgal abundance.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "The effect of textured surfaces on invertebrate abundance is varied.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "In some cases in the UK and the Netherlands, textured surfaces did not increase invertebrate abundance.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "In at least one case, textured surfaces had mixed effects on barnacle and mobile invertebrate abundances.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "In another case, textured surfaces increased barnacle abundance.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Creating natural rocky reef topography on intertidal artificial structures in the UK did not increase combined macroalgae and invertebrate species richness.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Creating natural rocky reef topography on intertidal artificial structures in the UK had mixed effects on barnacle and mobile invertebrate abundances depending on the site.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Topography created to mimic natural rocky reefs on intertidal artificial structures in the UK was colonized by macroalgae and limpets.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "Creating textures in conjunction with using environmentally-sensitive materials has also shown mixed results.",
    "citations": []
  },
  {
    "statement": "Using ECOncrete™ with grooves, ledges, and holes increased species richness and diversity.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Limestone-cement with pits, grooves, ridges, and texture had mixed effects on richness and diversity depending on the site.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "A combination of limestone-cement with pits, grooves, ridges, and texture had mixed effects on mobile invertebrate and barnacle abundance based on the site, wave-exposure, and material type.",
    "citations": [
      "3469"
    ]
  }
]

[
  {
    "statement": "A study in Italy found that subtidal artificial structures with harvesting restrictions had a different fish community composition compared to structures without restrictions.",
