    "citations": [
      "3457"
    ]
  },
  {
    "statement": "One study found that a subtidal artificial structure with harvesting restrictions supported species that were absent from unrestricted structures.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "A study in Italy reported similar total fish abundance around subtidal artificial structures with and without harvesting restrictions.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "In one study, fish abundances around artificial structures varied by species and survey date.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "One study found higher seabream abundances around a subtidal artificial structure that had harvesting restrictions.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "A study in Italy reported that legally restricting human access to subtidal artificial structures did not prevent people from harvesting invertebrates and fish.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "A study in Japan reported that creating small protrusions on a subtidal artificial structure had mixed effects on macroalgal abundance depending on the species.",
    "citations": [
      "3453"
    ]
