[
  {
    "statement": "A controlled study in the English Channel, UK, found that artificial reef modules made of scrap tyres developed a similar sessile invertebrate community composition as traditional artificial concrete modules.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "In the Mediterranean Sea, Israel, pyramid reefs made of “sea-friendly” concrete developed different invertebrate community compositions compared to reefs of either traditional concrete plinth-pole structures or bundles of traditional concrete tubes.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "One controlled study in the Mediterranean Sea found that invertebrate species richness was lower on “sea-friendly” pyramid reefs compared to bundle reefs of traditional concrete.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "Another controlled study in the Mediterranean Sea found that “sea-friendly” concrete pyramids had lower abundance compared to plinth-pole structures after two years.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "A controlled study in the Mediterranean Sea found that “sea-friendly” concrete pyramids had higher abundance compared to plinth-pole structures after three years.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "One replicated, controlled study in the Firth of Lorn, UK, found that the complexity of artificial reef modules had mixed effects on the abundance of edible crab and velvet swimming crab.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of using environmentally-sensitive materials on subtidal artificial structures in Australia.",
    "citations": [
      "2255",
      "2256",
      "2259"
    ]
  }
]

[
  {
    "statement": "Two studies examined the effects of managing or restricting the harvesting of species on intertidal artificial structures.",
